    "note": "1 obfuscated file."
   },
   {
    "area": "developer",
    "level": "low",
    "note": "No developer identity available."
   }
  ]
 },
 "asserted_findings": [
  {
   "number": 1,
   "kind": "verified-behavior",
   "severity": "critical",
   "category": "data-exfiltration",
   "title": "All browser cookies exfiltrated to external analytics host",
   "confidence": "high",
   "mechanism": "chrome.cookies.getAll({}) retrieves every cookie in every store, then fetch() POSTs the JSON-serialized cookie array to https://collect.evil-analytics-cdn.invalid/c",
   "detail": "The background service worker calls chrome.cookies.getAll with an empty filter object (retrieving all cookies across all domains and stores), then POSTs the entire cookie collection as JSON to the external host collect.evil-analytics-cdn.invalid. The .catch(() => {}) silently swallows errors, making this covert. The cross_file data flow confirms source_kind=cookie → fetch to dest_host=collect.evil-analytics-cdn.invalid (dest_party=external)."
  },
  {
   "number": 2,
   "kind": "verified-behavior",
   "severity": "critical",
   "category": "data-exfiltration",
   "title": "Obfuscated locale pack exfiltrates document.cookie to dynamic URL",
   "confidence": "high",
   "mechanism": "Obfuscated js/_locale_pack.js reads document.cookie, URL-encodes it, appends it to a dynamically-constructed base URL (_0xu), and fetch()es the result",
   "detail": "The file js/_locale_pack.js is flagged for obfuscation (string_array_decoder_detected=true, opaque_regions kind=obfuscated). It contains a fetch call whose URL is a concatenation of a variable _0xu (a dynamically resolved base URL) and encodeURIComponent(document.cookie). This exfiltrates the current page's cookies to an attacker-controlled endpoint. The file is imported by js/background.js."
  },
  {
   "number": 3,
   "kind": "verified-behavior",
   "severity": "high",
   "category": "messaging-surface",
   "title": "externally_connectable wildcard allows any web page to retrieve all cookies",
   "confidence": "high",
   "mechanism": "chrome.runtime.onMessageExternal listener accepts cmd==='getCookies' from any sender (no sender validation), calls chrome.cookies.getAll({}), and returns the full cookie array via sendResponse",
   "detail": "The manifest declares externally_connectable matching *://*/*, meaning any website can send messages to the extension. The onMessageExternal handler does not validate sender.id or sender.origin. Any web page that sends {cmd:'getCookies'} receives the complete cookie jar (chrome.cookies.getAll({}) with no domain filter). The message_graph confirms receiver_validates_sender=false for this edge."
  },
  {
   "number": 4,
   "kind": "observed-capability",
   "severity": "medium",
   "category": "permissions",
   "title": "Broad cookies + <all_urls> permission combination",
   "confidence": "high",
   "mechanism": null,
