  },
  {
   "number": 5,
   "kind": "observed-capability",
   "severity": "low",
   "category": "permissions",
   "title": "Clipboard write capability for cookie export",
   "confidence": "medium",
   "mechanism": null,
   "detail": "The extension uses clipboardWrite permission via document.execCommand('copy') in js/utils.js, likely for a cookie export/copy feature. The destination is the user's local clipboard (user-controlled channel), so this is low severity."
  }
 ],
